{
  "claims": [
    {
      "anchor": "In WAL mode writers do not block readers and readers do not block writers",
      "claim_text": "In WAL mode, writers do not block readers and readers do not block writers.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S0", "rel": "entails"},
        {"sid": "P1.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 6 states this directly; Passage 1 supports concurrent readers/writers."
    },
    {
      "anchor": "a read query against a WAL database never returns SQLITE_BUSY",
      "claim_text": "A read query against a WAL database never returns SQLITE_BUSY.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage 6 says some obscure cases can return SQLITE_BUSY, contradicting 'never'."
    },
    {
      "anchor": "If another connection has the database open in exclusive locking mode, though, all queries against it return SQLITE_BUSY",
      "claim_text": "If another connection has the database open in exclusive locking mode, all queries against it return SQLITE_BUSY.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Direct restatement of P7.S0."
    },
    {
      "anchor": "Chrome and Firefox open their database files this way",
      "claim_text": "Chrome and Firefox open their database files in exclusive locking mode.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P7.S1 states both open database files in exclusive locking mode."
    },
    {
      "anchor": "Firefox keeps its browsing history in a SQLite file called places.sqlite",
      "claim_text": "Firefox keeps its browsing history in a SQLite file called places.sqlite.",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "No passage mentions places.sqlite or Firefox browsing history."
    },
    {
      "anchor": "Once a connection has set EXCLUSIVE locking before its first WAL access, it can switch back with PRAGMA locking_mode=NORMAL",
      "claim_text": "A connection that set EXCLUSIVE locking before its first WAL access can switch back to NORMAL locking mode using PRAGMA locking_mode=NORMAL.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S1", "rel": "refutes"},
        {"sid": "P4.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P4.S1 says such attempts are no-ops; P4.S2 says must first leave WAL mode."
    },
    {
      "anchor": "If the last connection crashed, the next connection to open the database runs a recovery process while holding an exclusive lock",
      "claim_text": "If the last connection crashed, the next connection to open the database runs a recovery process while holding an exclusive lock.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P9.S0", "rel": "entails"},
        {"sid": "P9.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P9.S0 states recovery starts; P9.S1 states exclusive lock held during recovery."
    },
    {
      "anchor": "For a database that will only be accessed by threads within a single process, a custom VFS can put the wal-index in heap memory instead of shared memory",
      "claim_text": "For a database accessed only by threads within a single process, a custom VFS can implement the wal-index using heap memory instead of shared memory.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S1 gives exactly this example."
    },
    {
      "anchor": "exclusive locking mode also makes checkpoints run faster",
      "claim_text": "Exclusive locking mode makes checkpoints run faster.",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "No passage discusses checkpoint speed or exclusive locking mode affecting it."
    }
  ]
}
